  const auraProviderKey = isCurrentEnsembleChat ? 'ensemble' : currentProvider
  // ── Per-pane FX resolution (Multiview) ─────────────────────────────────────
  // Each pane renders its OWN sky/ghost/living-workspace INLINE (so FX show at
